insert into public.portfolio(data) values ('{"id":"ora","name":"ORA Objects","sector":"Jewellery","category":"Branding","color":"#e9d8b8","ink":"#292116","style":"ora","intro":"An identity for jewellery that becomes part of your everyday rituals.","problem":"Fine jewellery can feel reserved for special occasions. ORA needed a visual language that made meaningful pieces feel personal and approachable.","audience":"Design-conscious shoppers looking for everyday heirlooms.","strategy":"Pair sculptural product styling with a warm, quiet editorial system.","process":"Explore material palettes, refine the wordmark, and prototype packaging and product pages.","identity":"Champagne, ink and restrained serif typography.","deliverables":"Wordmark, packaging system, art direction and ecommerce concepts."}'::jsonb),
('{"id":"bloom","name":"Bloom Theory","sector":"Skincare","category":"UI/UX","color":"#d7e3bd","ink":"#29371b","style":"bloom","intro":"A clearer shopping experience for a calmer skincare routine.","problem":"A crowded product catalogue made it hard to build a simple routine.","audience":"Skincare shoppers who value ingredient transparency and practical advice.","strategy":"Organize the experience around routine steps and skin concerns.","process":"Map shopping journeys, prototype comparison cards and design mobile product pages.","identity":"Botanical green, warm paper and generous typography.","deliverables":"Shopping flows, reusable product components and a clickable design concept."}'::jsonb),
('{"id":"offbeat","name":"Offbeat Dept.","sector":"Fashion","category":"Creative Campaigns","color":"#ff8968","ink":"#281629","style":"offbeat","intro":"A streetwear launch built around the people who wear it.","problem":"The capsule needed a recognisable idea it could carry from launch to creator content.","audience":"Style-led young adults who discover fashion through communities and creators.","strategy":"Use expressive typography and day-in-the-life creative briefs.","process":"Develop the creative line, storyboard short-form edits and build a creator toolkit.","identity":"Electric orange, deep plum and offset lettering.","deliverables":"Launch concept, campaign artwork, creator briefs and social formats."}'::jsonb),
('{"id":"easy","name":"Easy Hours","sector":"Lifestyle","category":"Web Development","color":"#dcd1fa","ink":"#301b4c","style":"easy","intro":"A digital home for objects that make the day feel easier.","problem":"A small collection needed a storefront that made product details easy to explore.","audience":"People looking for thoughtful, practical objects for home and work.","strategy":"Use modular editorial storytelling with a direct path to product details.","process":"Map site navigation, prototype a responsive catalogue and set content rules.","identity":"Lavender, ink and a geometric display face.","deliverables":"Responsive storefront concept, content modules and product-page patterns."}'::jsonb);
